def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            pre_key = None
            has_pre = 1  # no prerelease -> sorts after
        else:
            has_pre = 0
            ids = pre.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident), ''))
                else:
                    pre_key.append((1, 0, ident))
            pre_key = tuple(pre_key)

        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

